struct folio *memfd_alloc_hugetlb_folio(struct hstate *h, struct file *file,
					pgoff_t idx, gfp_t gfp_mask)
{
	struct inode *inode = file_inode(file);
	struct resv_map *resv = inode_resv_map(inode);
	struct folio *folio;
	long chg;
	long regions_needed = 0;

	chg = region_chg(resv, idx, idx + 1, &regions_needed);
	if (chg == 0) {
		folio = alloc_hugetlb_folio_reserve(h, numa_node_id(),
						    NULL, gfp_mask);
	} else {
		folio = alloc_hugetlb_folio_nodemask(h, numa_node_id(),
						     NULL, gfp_mask, false);
		region_abort(resv, idx, idx + 1, regions_needed);
	}

	return folio;
}

